// ---- clean-room reference matcher for echo route patterns ----
// pattern segments: static, ":param" (one non-empty segment), "*" (rest, must be last)
func refMatch(pattern, path string) bool {
	if !strings.HasPrefix(path, "/") {
		return false
	}
	ps := strings.Split(pattern, "/") // leading "" for leading '/'
	xs := strings.Split(path, "/")
	// both start with "" (leading slash)
	for i := 0; i < len(ps); i++ {
		if ps[i] == "*" {
			// '*' consumes the rest of the path; requires the '/' separator to be present
			// i.e. there must be at least one more segment in the path than consumed so far
			if i >= len(xs) {
				return false
			}
			return true
		}
		if i >= len(xs) {
			return false
		}
		if strings.HasPrefix(ps[i], ":") {
			if xs[i] == "" {
				return false
			}
			continue
		}
		if ps[i] != xs[i] {
			return false
		}
	}
	return len(ps) == len(xs)
}

